<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;

SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$canManage=SchoolAuth::hasPermission('finance.manage');
if(!SchoolAuth::hasPermission('finance.view')){http_response_code(403);exit('Finance access is not permitted.');}
$pdo=SchoolDatabase::connection();$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
 elseif(!$canManage){http_response_code(403);exit('Finance changes are not permitted.');}
 else try{
  $action=(string)($_POST['action']??'');
  if($action==='create_fee'){
   $term=(int)($_POST['term_id']??0);$class=(int)($_POST['class_group_id']??0);$code=strtoupper(trim((string)($_POST['code']??'')));$label=trim((string)($_POST['label']??''));$amount=(float)($_POST['amount']??-1);$due=(string)($_POST['due_date']??'');
   if(!$term||!$class||!preg_match('/^[A-Z0-9_-]{2,40}$/',$code)||$label===''||$amount<0)throw new RuntimeException('Enter a valid fee code and label, term, class, and non-negative amount.');
   $q=$pdo->prepare('SELECT t.academic_year_id,c.academic_year_id class_year FROM terms t JOIN class_groups c ON c.id=:class WHERE t.id=:term');$q->execute(['class'=>$class,'term'=>$term]);$scope=$q->fetch();if(!$scope||(int)$scope['academic_year_id']!==(int)$scope['class_year'])throw new RuntimeException('The fee term and class must belong to the same academic year.');
   $q=$pdo->prepare('INSERT INTO fee_structures (term_id,class_group_id,code,label,amount,due_date) VALUES (:term,:class,:code,:label,:amount,:due)');$q->execute(['term'=>$term,'class'=>$class,'code'=>$code,'label'=>$label,'amount'=>number_format($amount,2,'.',''),'due'=>$due?:null]);(new AuditService())->record((int)$user['id'],'finance.fee.create','fee_structures',(int)$pdo->lastInsertId(),['code'=>$code]);$message='Fee item saved.';
  }elseif($action==='issue_invoices'){
   $term=(int)($_POST['term_id']??0);$class=(int)($_POST['class_group_id']??0);$q=$pdo->prepare('SELECT t.academic_year_id,c.academic_year_id class_year FROM terms t JOIN class_groups c ON c.id=:class WHERE t.id=:term');$q->execute(['class'=>$class,'term'=>$term]);$scope=$q->fetch();if(!$scope||(int)$scope['academic_year_id']!==(int)$scope['class_year'])throw new RuntimeException('Choose a matching term and class.');
   $fees=$pdo->prepare('SELECT id,label,amount,due_date FROM fee_structures WHERE term_id=:term AND class_group_id=:class ORDER BY id');$fees->execute(['term'=>$term,'class'=>$class]);$feeRows=$fees->fetchAll();if(!$feeRows)throw new RuntimeException('Add at least one fee structure for this class and term first.');
   $students=$pdo->prepare("SELECT s.id,s.admission_number FROM students s JOIN enrollments en ON en.student_id=s.id WHERE en.class_group_id=:class AND en.academic_year_id=:year AND en.status='active' AND s.status='active' ORDER BY s.id");$students->execute(['class'=>$class,'year'=>(int)$scope['academic_year_id']]);$studentRows=$students->fetchAll();if(!$studentRows)throw new RuntimeException('No active students are enrolled in this class.');
   $count=SchoolDatabase::transaction(function(PDO $pdo)use($studentRows,$feeRows,$term,$user):int{$existing=$pdo->prepare('SELECT id FROM invoices WHERE student_id=:student AND term_id=:term LIMIT 1');$insert=$pdo->prepare("INSERT INTO invoices (student_id,term_id,invoice_number,status,issued_at,due_at) VALUES (:student,:term,:number,'issued',UTC_TIMESTAMP(),:due)");$item=$pdo->prepare('INSERT INTO invoice_items (invoice_id,fee_structure_id,description,amount) VALUES (:invoice,:fee,:description,:amount)');$total=0;foreach($studentRows as $student){$existing->execute(['student'=>(int)$student['id'],'term'=>$term]);if($existing->fetchColumn())continue;$due=null;foreach($feeRows as $fee)if($fee['due_date']&&(!$due||$fee['due_date']>$due))$due=$fee['due_date'];$number='INV-'.$term.'-'.$student['admission_number'];$insert->execute(['student'=>(int)$student['id'],'term'=>$term,'number'=>$number,'due'=>$due]);$invoice=(int)$pdo->lastInsertId();foreach($feeRows as $fee)$item->execute(['invoice'=>$invoice,'fee'=>(int)$fee['id'],'description'=>$fee['label'],'amount'=>$fee['amount']]);$total++;}(new AuditService())->record((int)$user['id'],'finance.invoices.issue','class_groups',null,['term_id'=>$term,'invoices_created'=>$total]);return $total;});$message=$count?'Issued '.$count.' invoice(s). Existing invoices were left unchanged.':'Invoices already exist for all enrolled students.';
  }elseif($action==='record_payment'){
   $invoiceId=(int)($_POST['invoice_id']??0);$amount=(float)($_POST['amount']??0);$method=(string)($_POST['method']??'');$reference=trim((string)($_POST['reference']??''));$reason=trim((string)($_POST['note']??''));if(!$invoiceId||$amount<=0||!in_array($method,['cash','bank_transfer','mobile_money','cheque','other'],true))throw new RuntimeException('Choose an invoice, payment method, and positive amount.');
   $paymentId=SchoolDatabase::transaction(function(PDO $pdo)use($invoiceId,$amount,$method,$reference,$reason,$user):int{$q=$pdo->prepare("SELECT i.id,i.status,COALESCE((SELECT SUM(ii.amount-ii.discount) FROM invoice_items ii WHERE ii.invoice_id=i.id),0)+COALESCE((SELECT SUM(fa.amount) FROM financial_adjustments fa WHERE fa.invoice_id=i.id),0) total,COALESCE((SELECT SUM(pa.amount) FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.invoice_id=i.id AND p.status='succeeded'),0) paid FROM invoices i WHERE i.id=:id FOR UPDATE");$q->execute(['id'=>$invoiceId]);$invoice=$q->fetch();if(!$invoice||!in_array($invoice['status'],['issued','part_paid'],true))throw new RuntimeException('Only an issued invoice with an outstanding balance can receive payment.');$balance=round((float)$invoice['total']-(float)$invoice['paid'],2);if($amount>$balance+0.001)throw new RuntimeException('Payment is greater than the outstanding balance of '.money($balance).'.');$q=$pdo->prepare("INSERT INTO payments (payer_user_id,amount,currency,method,reference,status,idempotency_key) VALUES (:user,:amount,'TZS',:method,:reference,'succeeded',:key)");$q->execute(['user'=>(int)$user['id'],'amount'=>number_format($amount,2,'.',''),'method'=>$method,'reference'=>$reference?:null,'key'=>bin2hex(random_bytes(20))]);$pid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO payment_allocations (payment_id,invoice_id,amount) VALUES (:payment,:invoice,:amount)');$q->execute(['payment'=>$pid,'invoice'=>$invoiceId,'amount'=>number_format($amount,2,'.','')]);$status=abs($balance-$amount)<0.01?'paid':'part_paid';$q=$pdo->prepare('UPDATE invoices SET status=:status WHERE id=:id');$q->execute(['status'=>$status,'id'=>$invoiceId]);(new AuditService())->record((int)$user['id'],'finance.payment.record','payments',$pid,['invoice_id'=>$invoiceId,'amount'=>number_format($amount,2,'.',''),'method'=>$method,'note'=>$reason]);return $pid;});$message='Payment recorded. Reference: '.($reference?:'school receipt '.$paymentId).'.';
  } else throw new RuntimeException('That finance action is unavailable.');
 }catch(Throwable $exception){$error=$exception instanceof PDOException?'A database constraint rejected the finance record. Check for a duplicate fee code or payment reference.':$exception->getMessage();}
}
$terms=$pdo->query("SELECT t.id,t.name,y.name year_name,y.id year_id FROM terms t JOIN academic_years y ON y.id=t.academic_year_id ORDER BY y.starts_on DESC,t.starts_on DESC")->fetchAll();$classes=$pdo->query('SELECT c.id,c.name,c.academic_year_id,y.name year_name FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id ORDER BY y.starts_on DESC,c.name')->fetchAll();
$scopeSql='';$params=[];if($role==='parent_guardian'){$scopeSql="JOIN student_guardians sg ON sg.student_id=s.id JOIN guardians g ON g.id=sg.guardian_id AND g.user_id=:user AND sg.verification_status='verified' AND sg.ended_at IS NULL";$params['user']=(int)$user['id'];}elseif($role==='student'){$scopeSql='JOIN users u ON u.id=s.user_id AND u.id=:user';$params['user']=(int)$user['id'];}
$invoiceSql="SELECT i.id,i.invoice_number,i.status,i.due_at,s.full_name,s.admission_number,t.name term_name,y.name year_name,COALESCE((SELECT SUM(ii.amount-ii.discount) FROM invoice_items ii WHERE ii.invoice_id=i.id),0)+COALESCE((SELECT SUM(fa.amount) FROM financial_adjustments fa WHERE fa.invoice_id=i.id),0) total,COALESCE((SELECT SUM(pa.amount) FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.invoice_id=i.id AND p.status='succeeded'),0) paid FROM invoices i JOIN students s ON s.id=i.student_id JOIN terms t ON t.id=i.term_id JOIN academic_years y ON y.id=t.academic_year_id {$scopeSql} ORDER BY i.id DESC LIMIT 250";$q=$pdo->prepare($invoiceSql);$q->execute($params);$invoices=$q->fetchAll();
$fees=$canManage?$pdo->query('SELECT f.id,f.code,f.label,f.amount,f.due_date,t.name term_name,c.name class_name FROM fee_structures f JOIN terms t ON t.id=f.term_id JOIN class_groups c ON c.id=f.class_group_id ORDER BY f.id DESC LIMIT 100')->fetchAll():[];
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Fees & finance';require dirname(__DIR__).'/includes/header.php';
?>
