nrolment using the selected class and term fee schedule. Running it again leaves existing invoices unchanged.</p><form method="post" class="row g-2"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="issue_invoices"><div class="col-12"><label class="form-label">Term</label><select name="term_id" class="form-select" required><option value="">Choose term</option><?php foreach($terms as $term): ?><option value="<?= (int)$term['id'] ?>"><?= e($term['year_name'].' · '.$term['name']) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Class</label><select name="class_group_id" class="form-select" required><option value="">Choose class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['year_name'].' · '.$class['name']) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-outline-primary btn-sm"><i class="bi bi-send me-1"></i>Issue invoices</button></div></form></div></div></div></div><?php endif; ?>
